@extends('layouts.admin') @section('title',$post->exists?'Edit Post':'Create Post') @section('page-title',$post->exists?'Edit Post':'Create New Post') @section('content')<div class="admin-heading"><div><h1>{{$post->exists?'Edit Article':'Create New Article'}}</h1><p>Complete the details below and save your news story.</p></div><a class="admin-btn dark" href="{{route('dashboard.posts.index')}}"><i class="fas fa-arrow-left"></i>Back</a></div><section class="admin-card"><form class="admin-form" method="post" action="{{$post->exists?route('dashboard.posts.update',$post):route('dashboard.posts.store')}}">@csrf @if($post->exists)@method('put')@endif<label>Post Title *<input name="title" value="{{old('title',$post->title)}}" required placeholder="Enter post title"></label><div class="admin-form-grid"><label>Category<select name="category_id"><option value="">Select category</option>@foreach($categories as $category)<option value="{{$category->_id}}" @selected(old('category_id',$post->category_id)==(string)$category->_id)>{{$category->category_name}}</option>@endforeach</select></label><label>Status<select name="status"><option value="draft" @selected($post->status==='draft')>Draft</option><option value="pending" @selected($post->status==='pending')>Pending</option><option value="published" @selected($post->status==='published')>Published</option></select></label></div><label>Featured Image Path<input name="image" value="{{old('image',$post->image)}}" placeholder="posts/photo.jpg"></label><label>Article Content *<textarea name="content" style="min-height:330px" required placeholder="Write your article content...">{{old('content',$post->content)}}</textarea></label><div><button class="admin-btn"><i class="fas fa-save"></i>Save Post</button></div></form></section>@endsection
